 const exportSelected=async(kind:'pack'|'progress'|'mac'|'mac-intel'|'windows'|'archive')=>{if(!selected)return;if(['mac','mac-intel','windows'].includes(kind)&&selected.creation?.status==='draft'){fail('Create this game before exporting a playable app. You can export its notebook as a backup now.');return;}setExportBusy(true);try{await queue.current;if(failedSaves.current.has(`notebook:${selected.id}`))throw new Error('Save this game successfully before exporting. Your unsaved work is still available in the editor.');if(kind==='archive'){if(!window.asterloomDesktop?.exportNotebookArchive)throw new Error('Open the desktop studio to export a notebook with large recordings.');const result=await window.asterloomDesktop.exportNotebookArchive(serializePackage(selected));if(result.canceled)return;if(result.error)throw new Error(result.error);setExportNotice(`Notebook and ${result.assetCount||0} recording files saved to ${result.path}.`);}else if(kind==='pack')download(serializePackage(await materializeNotebookMedia(selected)),`${slug(selected.title)}.learnpack`);else if(kind==='progress'){if(failedSaves.current.has(`progress:${selected.id}`))throw new Error('Retry saving learning progress before exporting this progress backup.');download(await serializeNotebookProgress(selected,committedProgressRef.current[selected.id]||emptyProgress(selected.id)),`${slug(selected.title)}.progress.json`);}else if(window.asterloomDesktop){const result=await window.asterloomDesktop.exportGame(serializePackage(selected),kind);if(result.canceled)return;if(result.error)throw new Error(result.error);if(result.warning){setExportNotice(`Saved to ${result.path}. ${result.warning}`);}else setExportNotice(`Game bundle saved: ${result.path}`);}else{throw new Error('Open this notebook in the Asterloom desktop application to export a playable Mac or Windows application.');}notify('Export prepared. Your original notebook stays in your library.');}catch(e){fail((e as Error).message);}finally{setExportBusy(false);}};
 const doRefine=async()=>{if(!selected)return;setAiBusy(true);try{const result=await refineCards(selected,aiConfig,undefined,async receipt=>{const current=notebookRef.current.find(n=>n.id===selected.id);if(!current)return false;return save({...current,aiToolReceipts:upsertAIUsageReceipt(current.aiToolReceipts,receipt)});});const current=notebookRef.current.find(n=>n.id===selected.id);if(!current||JSON.stringify([current.sources,current.cards])!==JSON.stringify([selected.sources,selected.cards]))throw new Error('This notebook changed while the wording draft was being prepared. Your latest edits were kept. Run refinement again against the updated material.');save({...current,cards:result.cards,updatedAt:new Date().toISOString()});setModal(null);notify('The wording draft is ready. Review the changes before sharing.');}catch(e){fail((e as Error).message);}finally{setAiBusy(false);}};
